static long rob(int[] rewards) {
    long two=0,one=0;
    for(int x:rewards) {
        long current=Math.max(one,two+x); two=one; one=current;
    }
    return one;
}

problems.kotlin:
fun rob(rewards: IntArray): Long {
    var two = 0L; var one = 0L
    for (x in rewards) {
        val current = maxOf(one, two + x); two = one; one = current
    }
    return one
}

